public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLength = 0;

    for (int length = 1; length <= strings.get(0).length(); length++) {
        for (int start = 0; start <= strings.get(0).length() - length; start++) {
            String substring = strings.get(0).substring(start, start + length);
            String reversedSubstring = new StringBuilder(substring).reverse().toString();
            boolean allContains = true;
            for (String str : strings) {
                if (!str.contains(substring) && !str.contains(reversedSubstring)) {
                    allContains = false;
                    break;
                }
            }
            if (allContains) {
                maxLength = length;
            }
        }
    }

    return maxLength;
}

public int findLargestSubstring(List<String> strings) {
    int maxLength = 0;
    if (strings == null || strings.isEmpty()) {
        return maxLength;
    }

    // Start with the first string and check all possible substrings
    String firstString = strings.get(0);
    int n = firstString.length();

    // Generate all substrings of the first string
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j <= n; j++) {
            String substring = firstString.substring(i, j);
            String reversedSubstring = new StringBuilder(substring).reverse().toString();

            boolean isCommon = true;
            for (String str : strings) {
                if (!str.contains(substring) && !str.contains(reversedSubstring)) {
                    isCommon = false;
                    break;
                }
            }

            if (isCommon) {
                maxLength = Math.max(maxLength, substring.length());
            }
        }
    }

    return maxLength;
}

