private static boolean isValid(char[][] grid, boolean[][] visited, int row, int col) {
    return row >= 0 && row < grid.length && col >= 0 && col < grid[0].length && grid[row][col] == '@' && !visited[row][col];
}

public static int countOilDeposits(char[][] grid) {
    int count = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                count++;
                markDeposit(grid, i, j);
            }
        }
    }
    return count;
}

private static void markDeposit(char[][] grid, int i, int j) {
    if (i < 0 || i >= grid.length || j < 0 || j >= grid[i].length || grid[i][j] != '@') {
        return;
    }
    grid[i][j] = '*';
    markDeposit(grid, i - 1, j);
    markDeposit(grid, i + 1, j);
    markDeposit(grid, i, j - 1);
    markDeposit(grid, i, j + 1);
    markDeposit(grid, i - 1, j - 1);
    markDeposit(grid, i - 1, j + 1);
    markDeposit(grid, i + 1, j - 1);
    markDeposit(grid, i + 1, j + 1);
}

public static int maxRegions(int N) {
    if (N == 0) return 1;
    if (N == 1) return 2;
    int regions = 8;
    for (int i = 2; i < N; i++) {
        regions += 3 * i + 2;
    }
    return regions;
}

