}

public static int maxRegions(int N) {
    if (N == 0) return 1;
    if (N == 1) return 2;
    return 2 + 3 * N + (N * (N - 1)) / 2;
}

public static int maxRegions(int N) {
    if (N == 0) return 1;
    if (N == 1) return 2;
    return maxRegions(N - 1) + 2 * (N - 1) + 2;
}

public static int maxRegions(int N) {
    if (N == 0) return 1; // Base case: no triangles, one region (the whole plane)
    int regions = 2; // Starting with one triangle which divides the plane into 2 regions
    for (int i = 1; i < N; i++) {
        regions += 4 * i + 2; // Each new triangle can intersect all previous edges creating 4 new regions plus 2 more
    }
    return regions;
}

