public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] visited = new boolean[n][n];
    return canTravel(n, start[0], start[1], end[0], end[1], paths, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravel(int n, int x, int y, int ex, int ey, int[][] paths, boolean[][] visited) {
    if (x < 0 || x >= n || y < 0 || y >= n || visited[x][y]) {
        return false;
    }
    if (x == ex && y == ey) {
        return true;
    }
    visited[x][y] = true;
    for (int[] path : paths) {
        if (path[0] == x && path[1] == y) {
            if (canTravel(n, x + path[2], y + path[3], ex, ey, paths, visited)) {
                return true;
            }
        }
    }
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] visited = new boolean[n][n];
    return canTravelHelper(n, start[0], start[1], end[0], end[1], paths, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravelHelper(int n, int currentX, int currentY, int endX, int endY, int[][] paths, boolean[][] visited) {
    if (currentX == endX && currentY == endY) {
        return true;
    }
    visited[currentX][currentY] = true;
    for (int[] path : paths) {
        int nextX = currentX + path[0];
        int nextY = currentY + path[1];
        if (isValid(n, nextX, nextY) && !visited[nextX][nextY] && canTravelHelper(n, nextX, nextY, endX, endY, paths, visited)) {
            return true;
        }
    }
    return false;
}

private static boolean isValid(int n, int x, int y) {
    return x >= 0 && x < n && y >= 0 && y < n;
}

