private static boolean canTravel(int n, int x, int y, int ex, int ey, int[][] paths, boolean[][] visited) {
    if (x == ex && y == ey) return true;
    if (x < 0 || x >= n || y < 0 || y >= n || visited[x][y]) return false;
    visited[x][y] = true;
    for (int[] path : paths) {
        if (path[0] == x && path[1] == y) {
            if (canTravel(n, path[2], path[3], ex, ey, paths, visited)) return true;
        } else if (path[2] == x && path[3] == y) {
            if (canTravel(n, path[0], path[1], ex, ey, paths, visited)) return true;
        }
    }
    return false;
}

public static String appx(String word1, String word2) {
    StringBuilder commonLetters = new StringBuilder();
    String longer = word1.length() >= word2.length() ? word1 : word2;
    String shorter = word1.length() < word2.length() ? word1 : word2;

    for (char c : shorter.toCharArray()) {
        if (longer.indexOf(c) != -1 && commonLetters.indexOf(String.valueOf(c)) == -1) {
            commonLetters.append(c);
        }
    }

    int commonCount = commonLetters.length();
    int sumOfLengths = word1.length() + word2.length();

    int gcd = gcd(commonCount, sumOfLengths);
    commonCount /= gcd;
    sumOfLengths /= gcd;

    return "appx(" + word1 + ", " + word2 + ") = " + commonCount + "/" + sumOfLengths;
}

