    String[] weekdays = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};

    // Zeller's Congruence Algorithm
    if (month < 3) {
        month += 12;
        year -= 1;
    }
    int k = year % 100;
    int j = year / 100;
    int f = day + (13 * (month + 1)) / 5 + k + k / 4 + j / 4 + 5 * j;
    int dayOfWeek = (f % 7 + 5) % 7; // Adjusting Zeller's result to match Java's calendar

    return months[month - 1] + " " + day + ", " + year + " is a " + weekdays[dayOfWeek];
}

