public int findMinFibonacciNumbers(int k) {
    if (k <= 1) return k;

    int a = 1, b = 1;
    while (b <= k) {
        int temp = b;
        b = a + b;
        a = temp;
    }

    return 1 + findMinFibonacciNumbers(k - a);
}

public int findMinFibonacciNumbers(int k) {
    if (k < 1) return 0;
    int a = 1, b = 1;
    while (b <= k) {
        int temp = a;
        a = b;
        b = temp + b;
    }
    return 1 + findMinFibonacciNumbers(k - a);
}

