public int findMinFibonacciNumbers(int k) {
    int a = 1, b = 1;
    while (b <= k) {
        int temp = a + b;
        a = b;
        b = temp;
    }
    int count = 0;
    while (k > 0) {
        int temp = a + b;
        a = b;
        b = temp;
        while (b > k) {
            b = a;
            a = temp - a;
        }
        k -= b;
        count++;
    }
    return count;
}

