public int maxUniqueSplit(String s) {
    return helper(s, new HashSet<>());
}

private int helper(String s, HashSet<String> used) {
    if (s.isEmpty()) {
        return 0;
    }
    int maxUnique = 0;
    for (int i = 1; i <= s.length(); i++) {
        String substring = s.substring(0, i);
        if (!used.contains(substring)) {
            used.add(substring);
            maxUnique = Math.max(maxUnique, 1 + helper(s.substring(i), used));
            used.remove(substring);
        }
    }
    return maxUnique;
}

