private static void backtrack(int[] A, boolean[] used, List<Integer> path, int[] count) {
    if (path.size() == A.length) {
        count[0]++;
        return;
    }

    Set<Integer> seen = new HashSet<>();
    for (int i = 0; i < A.length; i++) {
        if (used[i] || (path.size() > 0 && seen.contains(A[i])) || (path.size() > 0 && !isPerfectSquare(path.get(path.size() - 1) + A[i]))) {
            continue;
        }

        used[i] = true;
        path.add(A[i]);
        seen.add(A[i]);
        backtrack(A, used, path, count);
        used[i] = false;
        path.remove(path.size() - 1);
    }
}

