public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];

    left[0] = -1;
    right[n - 1] = n;

    for (int i = 1; i < n; i++) {
        int p = i - 1;
        while (p >= 0 && heights[p] >= heights[i]) {
            p = left[p];
        }
        left[i] = p;
    }

    for (int i = n - 2; i >= 0; i--) {
        int p = i + 1;
        while (p < n && heights[p] >= heights[i]) {
            p = right[p];
        }
        right[i] = p;
    }

    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, heights[i] * (right[i] - left[i] - 1));
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] stack = new int[n];
    int maxArea = 0;
    int top = -1;
    int i = 0;
    while (i < n) {
        if (top == -1 || heights[stack[top]] <= heights[i]) {
            stack[++top] = i++;
        } else {
            int h = heights[stack[top--]];
            int left = top == -1 ? i : i - stack[top] - 1;
            maxArea = Math.max(maxArea, h * left);
        }
    }
    while (top != -1) {
        int h = heights[stack[top--]];
        int left = top == -1 ? i : i - stack[top] - 1;
        maxArea = Math.max(maxArea, h * left);
    }
    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];

    Stack<Integer> stack = new Stack<>();

    // Fill left array
    for (int i = 0; i < n; i++) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        left[i] = stack.isEmpty() ? 0 : stack.peek() + 1;
        stack.push(i);
    }

    stack.clear();

    // Fill right array
    for (int i = n - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        right[i] = stack.isEmpty() ? n - 1 : stack.peek() - 1;
        stack.push(i);
    }

    // Calculate the maximum area
    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, heights[i] * (right[i] - left[i] + 1));
    }

    return maxArea;
}

