public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) return result;
    if (n == 1) return Arrays.asList("0", "1", "8");
    if (n == 2) return Arrays.asList("11", "69", "88", "96");

    List<String> subResult = centerSymmetricNumbers(n - 2);
    for (String num : subResult) {
        result.add("1" + num + "1");
        result.add("6" + num + "9");
        result.add("8" + num + "8");
        result.add("9" + num + "6");
    }

    return result;
}

