private static List<String> helper(int current, int target) {
    if (current == 0) return new ArrayList<>(Arrays.asList(""));
    if (current == 1) return new ArrayList<>(Arrays.asList("0", "1", "8"));

    List<String> subResults = helper(current - 2, target);
    List<String> results = new ArrayList<>();

    for (String subResult : subResults) {
        if (current != target) results.add("0" + subResult + "0");
        results.add("1" + subResult + "1");
        results.add("6" + subResult + "9");
        results.add("8" + subResult + "8");
        results.add("9" + subResult + "6");
