private static List<String> generateCenterSymmetricNumbers(int current, int total) {
    if (current == 0) return new ArrayList<>(Arrays.asList(""));
    if (current == 1) return new ArrayList<>(Arrays.asList("0", "1", "8"));

    List<String> prev = generateCenterSymmetricNumbers(current - 2, total);
    List<String> result = new ArrayList<>();

    for (String s : prev) {
        if (current != total) result.add("0" + s + "0");
        result.add("1" + s + "1");
        result.add("6" + s + "9");
        result.add("8" + s + "8");
        result.add("9" + s + "6");
    }

    return result;
}

public static boolean isBoomerang(int[][] points) {
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Calculate the area of the triangle formed by the points
    // If the area is 0, the points are collinear and do not form a boomerang
    return (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) != 0;
}

public static boolean isBoomerang(int[][] points) {
