public static int calculateUniqueSum(int[] nums) {
    int sum = 0;
    boolean[] seen = new boolean[2001]; // Assuming nums[i] is between -1000 and 1000
    boolean[] duplicate = new boolean[2001];

    for (int num : nums) {
        if (!seen[num + 1000]) {
            sum += num;
            seen[num + 1000] = true;
        } else if (!duplicate[num + 1000]) {
            sum -= num;
            duplicate[num + 1000] = true;
        }
    }

    return sum;
}

public static int calculateUniqueSum(int[] nums) {
    int sum = 0;
    int[] count = new int[1001]; // Assuming nums[i] is in the range [0, 1000]
    for (int num : nums) {
        count[num]++;
    }
    for (int i = 0; i < count.length; i++) {
        if (count[i] == 1) {
            sum += i;
        }
    }
    return sum;
}

